-- SPDX-License-Identifier: AGPL-3.0-or-later
-- risk: additive
--
-- 0539 -- one setup status (#2867, ADR 0047).
--
-- The setup guide reads ONE answer: every step of the shared catalogue
-- (`setup_step_catalogue()`, generated by tool/build_setup_steps.dart from
-- lib/features/workspace/domain/setup_steps.dart) with its state computed
-- from what the workspace actually holds, and the four outcome milestones
-- (bookable, money, invoice, live). It reuses the readiness sections (0399)
-- and the local slots (0280) and adds the detectors they never had: VAT
-- rates, numbering, the document layout, e-invoicing, the accounting book,
-- reminders, services, purchases, the lease, the assets, the kiosk, the
-- brand and the public page. `workspace_readiness` stays as it is for its
-- readers until they move.
--
-- A step the server can verify is ready only from its evidence. Only a
-- `manual` step reads ready when the owner marked it done (an
-- acknowledgement); on any other optional step an acknowledgement means
-- deferred, never done.

create or replace function public.setup_step_catalogue()
returns jsonb language sql immutable set search_path = public as $fn$
  select $json$[{"id":"basics","group":"open","milestone":"bookable","route":"/workspace-settings","evidence":"basics","feature":null,"required":true,"depends_on":[],"actor":"owner","estimate_minutes":3},{"id":"hours","group":"open","milestone":"bookable","route":"/availability","evidence":"hours","feature":null,"required":true,"depends_on":["basics"],"actor":"owner","estimate_minutes":5},{"id":"places","group":"open","milestone":"bookable","route":"/editor","evidence":"places","feature":null,"required":true,"depends_on":["basics"],"actor":"owner","estimate_minutes":10},{"id":"member_rights","group":"open","milestone":"bookable","route":"/roles","evidence":"member_rights","feature":null,"required":true,"depends_on":[],"actor":"owner","estimate_minutes":1},{"id":"invite","group":"open","milestone":"bookable","route":"/workspace-code","evidence":"invite","feature":null,"required":false,"depends_on":["member_rights"],"actor":"owner","estimate_minutes":3},{"id":"pricing","group":"run","milestone":"money","route":"/billing","evidence":"pricing","feature":"moneyTab","required":true,"depends_on":[],"actor":"owner","estimate_minutes":10},{"id":"services","group":"run","milestone":"money","route":"/services","evidence":"services","feature":"services","required":false,"depends_on":[],"actor":"owner","estimate_minutes":5},{"id":"payment_methods","group":"run","milestone":"money","route":"/payment-methods","evidence":"payment_methods","feature":"moneyTab","required":true,"depends_on":["pricing"],"actor":"owner","estimate_minutes":5},{"id":"online_payments","group":"run","milestone":"money","route":"/payment-config","evidence":"online_payments","feature":"onlinePayments","required":true,"depends_on":["payment_methods"],"actor":"operator","estimate_minutes":5},{"id":"approvals","group":"run","milestone":"money","route":"/validation","evidence":"approvals","feature":null,"required":true,"depends_on":["invite"],"actor":"owner","estimate_minutes":5},{"id":"new_members","group":"run","milestone":"live","route":"/workspace-settings","evidence":"manual","feature":null,"required":false,"depends_on":[],"actor":"owner","estimate_minutes":3},{"id":"kiosk","group":"run","milestone":"live","route":"/nfc-config","evidence":"kiosk","feature":"kioskMode","required":false,"depends_on":[],"actor":"owner","estimate_minutes":5},{"id":"purchases","group":"run","milestone":"money","route":"/money/purchases","evidence":"purchases","feature":"purchases","required":false,"depends_on":[],"actor":"owner","estimate_minutes":5},{"id":"lease","group":"run","milestone":"money","route":"/money/purchases","evidence":"lease","feature":"premisesLease","required":false,"depends_on":[],"actor":"owner","estimate_minutes":5},{"id":"assets","group":"run","milestone":"money","route":"/money/purchases","evidence":"assets","feature":"assetRegister","required":false,"depends_on":[],"actor":"owner","estimate_minutes":5},{"id":"look","group":"run","milestone":"live","route":"/settings/colours","evidence":"look","feature":"workspaceBranding","required":false,"depends_on":[],"actor":"owner","estimate_minutes":5},{"id":"public_page","group":"run","milestone":"live","route":"/settings/public-page","evidence":"public_page","feature":"publicListings","required":false,"depends_on":[],"actor":"owner","estimate_minutes":5},{"id":"legal_identity","group":"grow","milestone":"invoice","route":"/legal-identity","evidence":"legal_identity","feature":"invoicing","required":true,"depends_on":[],"actor":"owner","estimate_minutes":5},{"id":"vat","group":"grow","milestone":"invoice","route":"/vat","evidence":"vat","feature":"vatManagement","required":true,"depends_on":["legal_identity"],"actor":"owner","estimate_minutes":5},{"id":"numbering","group":"grow","milestone":"invoice","route":"/settings/number-sequences","evidence":"numbering","feature":"numberSequences","required":true,"depends_on":["legal_identity"],"actor":"owner","estimate_minutes":3},{"id":"documents","group":"grow","milestone":"invoice","route":"/reports","evidence":"documents","feature":"invoicePdfTemplate","required":false,"depends_on":["legal_identity"],"actor":"owner","estimate_minutes":5},{"id":"einvoicing","group":"grow","milestone":"invoice","route":"/einvoice-config","evidence":"einvoicing","feature":"einvoiceCustomerDelivery","required":true,"depends_on":["legal_identity","numbering"],"actor":"owner","estimate_minutes":15},{"id":"accounting","group":"grow","milestone":"invoice","route":"/legal-identity","evidence":"accounting","feature":"accountingBook","required":true,"depends_on":["vat"],"actor":"owner","estimate_minutes":10},{"id":"reminders","group":"grow","milestone":"invoice","route":"/settings/payment-terms","evidence":"reminders","feature":"dunning","required":false,"depends_on":[],"actor":"owner","estimate_minutes":5},{"id":"first_booking","group":"launch","milestone":"live","route":"/reserve","evidence":"first_booking","feature":null,"required":true,"depends_on":["places","member_rights"],"actor":"owner","estimate_minutes":5},{"id":"recovery","group":"launch","milestone":"live","route":"/workspace-settings","evidence":"recovery","feature":null,"required":false,"depends_on":[],"actor":"owner","estimate_minutes":2},{"id":"assistant","group":"launch","milestone":"live","route":"/settings/assistant-setup","evidence":"assistant","feature":"mcpAccess","required":false,"depends_on":[],"actor":"operator","estimate_minutes":5}]$json$::jsonb;
$fn$;
revoke execute on function public.setup_step_catalogue() from public, anon;
grant execute on function public.setup_step_catalogue() to authenticated;

create or replace function public.workspace_setup_status(p_workspace_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  w public.workspaces;
  v_sections jsonb;
  v_local jsonb;
  v_evidence jsonb;
  v_steps jsonb := '[]'::jsonb;
  v_state jsonb := '{}'::jsonb;
  v_step jsonb;
  v_applies boolean;
  v_ready boolean;
  v_acknowledged boolean;
  v_status text;
  v_reason text;
  v_blocked jsonb;
  v_required boolean;
  v_milestones jsonb := '[]'::jsonb;
  v_m text;
  v_order text[] := array['bookable', 'money', 'invoice', 'live'];
  v_rank int;
begin
  if auth.uid() is null or not public.has_permission(p_workspace_id, 'manageConfiguration') then
    raise exception 'only someone who configures this workspace sees how ready it is';
  end if;
  select * into w from public.workspaces where id = p_workspace_id;
  v_sections := public.workspace_readiness(p_workspace_id);
  v_local := public.workspace_local_readiness(p_workspace_id);

  -- Each detector: the section's own state where readiness already knows,
  -- the workspace's rows where it does not.
  v_evidence := jsonb_build_object(
    'basics', coalesce(w.timezone, '') <> '' and coalesce(w.currency_code, '') <> '',
    'hours', exists (select 1 from jsonb_array_elements(v_sections) s
                      where s->>'section' = 'region_rules' and s->>'state' = 'ready'),
    'places', exists (select 1 from jsonb_array_elements(v_sections) s
                       where s->>'section' = 'resources' and s->>'state' = 'ready'),
    'member_rights', exists (select 1 from jsonb_array_elements(v_sections) s
                              where s->>'section' = 'member_permissions' and s->>'state' = 'ready'),
    'invite', exists (select 1 from jsonb_array_elements(v_sections) s
                       where s->>'section' = 'invitations' and s->>'state' = 'ready'),
    'pricing', exists (select 1 from jsonb_array_elements(v_sections) s
                        where s->>'section' = 'pricing' and s->>'state' = 'ready'),
    'services', exists (select 1 from public.services where workspace_id = p_workspace_id and active),
    'payment_methods', exists (select 1 from jsonb_array_elements(v_sections) s
                                where s->>'section' = 'payments' and s->>'state' = 'ready'),
    'online_payments', exists (select 1 from jsonb_array_elements(v_local) l
                                where l->>'slot' = 'payment_provider' and coalesce((l->>'filled')::boolean, false)),
    'approvals', not exists (select 1 from jsonb_array_elements(v_sections) s
                              where s->>'section' = 'roles_validation' and s->>'state' = 'needs_configuration'),
    'kiosk', exists (select 1 from public.members where workspace_id = p_workspace_id
                      and is_kiosk and status = 'active'),
    'purchases', exists (select 1 from public.suppliers where workspace_id = p_workspace_id),
    'lease', exists (select 1 from public.premises_leases where workspace_id = p_workspace_id),
    'assets', exists (select 1 from public.workspace_assets where workspace_id = p_workspace_id),
    'look', jsonb_typeof(w.branding) = 'object' and w.branding <> '{}'::jsonb,
    'public_page', exists (select 1 from public.workspace_public_pages where workspace_id = p_workspace_id),
    'legal_identity', not exists (select 1 from jsonb_array_elements(v_sections) s
                                   where s->>'section' = 'legal_identity' and s->>'state' <> 'ready'),
    'vat', exists (select 1 from public.vat_rates where workspace_id = p_workspace_id),
    'numbering', exists (select 1 from public.number_sequences where workspace_id = p_workspace_id),
    'documents', w.invoice_pdf_template is not null and w.invoice_pdf_template::text not in ('{}', 'null', '""'),
    'einvoicing', exists (select 1 from jsonb_array_elements(v_local) l
                           where l->>'slot' = 'einvoice_platform' and coalesce((l->>'filled')::boolean, false)),
    'accounting', exists (select 1 from public.book_profiles where workspace_id = p_workspace_id),
    'reminders', jsonb_typeof(w.dunning_rules) = 'object' and w.dunning_rules <> '{}'::jsonb,
    'first_booking', exists (select 1 from jsonb_array_elements(v_sections) s
                              where s->>'section' = 'first_booking' and s->>'state' = 'ready'),
    'recovery', exists (select 1 from jsonb_array_elements(v_sections) s
                         where s->>'section' = 'recovery' and s->>'state' = 'ready'),
    'assistant', exists (select 1 from jsonb_array_elements(v_sections) s
                          where s->>'section' = 'assistant' and s->>'state' = 'ready'));

  -- First pass: applies, ready, acknowledged.
  for v_step in select e from jsonb_array_elements(public.setup_step_catalogue()) e loop
    v_applies := v_step->>'feature' is null
                 or public.feature_effective(p_workspace_id, v_step->>'feature');
    v_acknowledged := exists (
      select 1 from public.readiness_acknowledgements a
       where a.installation_id = public.installation_id()
         and a.workspace_id = p_workspace_id
         and a.user_id = auth.uid()
         and a.section = v_step->>'id');
    v_ready := case when v_step->>'evidence' = 'manual' then v_acknowledged
                    else coalesce((v_evidence->>(v_step->>'evidence'))::boolean, false) end;
    v_state := v_state || jsonb_build_object(v_step->>'id',
      jsonb_build_object('applies', v_applies, 'ready', v_ready, 'acknowledged', v_acknowledged));
  end loop;

  -- Second pass: the state each step shows, with what blocks it.
  for v_step in select e from jsonb_array_elements(public.setup_step_catalogue()) e loop
    v_applies := (v_state->(v_step->>'id')->>'applies')::boolean;
    v_ready := (v_state->(v_step->>'id')->>'ready')::boolean;
    v_acknowledged := (v_state->(v_step->>'id')->>'acknowledged')::boolean;
    v_required := (v_step->>'required')::boolean
      -- an approval rule nobody can satisfy holds requests forever (0399)
      or (v_step->>'id' = 'approvals' and not v_ready);
    select coalesce(jsonb_agg(d), '[]'::jsonb) into v_blocked
      from jsonb_array_elements_text(v_step->'depends_on') d
     where coalesce((v_state->d->>'applies')::boolean, false)
       and not coalesce((v_state->d->>'ready')::boolean, false);
    v_reason := null;
    v_status := case
      when not v_applies then 'not_applicable'
      when v_ready then 'ready'
      when jsonb_array_length(v_blocked) > 0 then 'blocked'
      when not v_required and v_acknowledged then 'deferred'
      when v_step->>'actor' = 'operator' then 'needs_operator'
      else 'needs_configuration' end;
    if v_status = 'needs_operator' then v_reason := 'operator_prerequisite'; end if;
    v_steps := v_steps || jsonb_build_array(jsonb_build_object(
      'step', v_step->>'id',
      'group', v_step->>'group',
      'milestone', v_step->>'milestone',
      'required', v_required,
      'state', v_status,
      'reason', v_reason,
      'blocked_by', v_blocked,
      'route', v_step->>'route',
      'actor', v_step->>'actor',
      'manual', v_step->>'evidence' = 'manual',
      'estimate_minutes', (v_step->>'estimate_minutes')::int));
  end loop;

  -- A milestone is reached when every required, applicable step of it and
  -- of the milestones before it is ready; one with no step that applies
  -- does not concern this workspace.
  foreach v_m in array v_order loop
    v_rank := array_position(v_order, v_m);
    v_milestones := v_milestones || jsonb_build_array((
      select jsonb_build_object(
        'milestone', v_m,
        'applies', bool_or(s->>'milestone' = v_m and s->>'state' <> 'not_applicable'),
        'required', count(*) filter (where (s->>'required')::boolean and s->>'state' <> 'not_applicable'),
        'ready', count(*) filter (where (s->>'required')::boolean and s->>'state' = 'ready'),
        'reached', coalesce(bool_and(s->>'state' in ('ready', 'not_applicable'))
                              filter (where (s->>'required')::boolean), true))
        from jsonb_array_elements(v_steps) s
       where array_position(v_order, s->>'milestone') <= v_rank));
  end loop;

  return jsonb_build_object('version', 8, 'steps', v_steps, 'milestones', v_milestones);
end;
$fn$;
revoke execute on function public.workspace_setup_status(uuid) from public, anon;
grant execute on function public.workspace_setup_status(uuid) to authenticated;

select public.set_deskilo_schema_version(539);
